function validate([s, count]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 30000) return 's needs 1 to 30000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (!Number.isInteger(count) || count < 1 || count > 30000) return 'count is an integer from 1 to 30000.';
  return null;
}

