function equalCountSubstrings(s, count) {
  let total = 0;
  for (let unique = 1; unique <= 26; unique++) {
    const size = unique * count;
    if (size > s.length) {
      break;
    }
    const freq = new Array(26).fill(0);
    let exact = 0;
    for (let right = 0; right < s.length; right++) {
      const added = s.charCodeAt(right) - 97;
      freq[added]++;
      if (freq[added] === count) {
        exact++;
      } else if (freq[added] === count + 1) {
        exact--;
      }
      const left = right - size;
      if (left >= 0) {
        const removed = s.charCodeAt(left) - 97;
        if (freq[removed] === count) {
          exact--;
        } else if (freq[removed] === count + 1) {
          exact++;
        }
        freq[removed]--;
      }
      if (right >= size - 1 && exact === unique) {
        total++;
      }
    }
  }
  return total;
}

