function equalCountSubstrings(s, count) {
  let answer = 0;
  for (let start = 0; start < s.length; start++) {
    const seen = new Map();
    for (let end = start; end < s.length; end++) {
      seen.set(s[end], (seen.get(s[end]) || 0) + 1);
      if ([...seen.values()].every(v => v === count)) answer++;
    }
  }
  return answer;
}

