function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const alphabet = letters.slice(0, int(1, 4));
    const n = int(1, 12);
    const s = Array.from({ length: n }, () => alphabet[int(0, alphabet.length - 1)]).join('');
    return [s, rand() < 0.1 ? int(5, 30000) : int(1, 4)];
  }
  // Large: glue together blocks where a few letters each appear exactly count times, plus some noise.
  const count = [1, 2, 3, 5, 40][int(0, 4)];
  const alphabet = letters.slice(0, int(2, 26));
  const n = 10000;
  let s = '';
  while (s.length < n) {
    if (rand() < 0.7) {
      const picked = [...alphabet].sort(() => rand() - 0.5).slice(0, int(1, Math.min(alphabet.length, 6)));
      const block = picked.flatMap(ch => Array(count).fill(ch));
      for (let i = block.length - 1; i > 0; i--) { const j = int(0, i); [block[i], block[j]] = [block[j], block[i]]; }
      s += block.join('');
    } else {
      s += alphabet[int(0, alphabet.length - 1)];
    }
  }
  return [s.slice(0, n), count];
}
